package com.englishdoctor.vocabsolution.data

import kotlinx.serialization.Serializable

// Data classes mirror the JSON files in assets/content (generated by tools/extract/parse_book.py).

@Serializable
data class Suffix(
    val id: String,
    val affix: String,
    val meaningBn: String,
    val examples: List<String>,
    val posFormed: String? = null,
)

@Serializable
data class Prefix(
    val id: String,
    val affix: String,
    val meaningBn: String,
    val examples: List<String>,
    val typeBn: String? = null,
)

@Serializable
data class WordAnalysis(
    val id: String,
    val word: String,
    val pos: String,
    val parts: List<String>,
    val meaningBn: String,
)

@Serializable
data class MultiplyingWord(val id: String, val order: Int, val word: String)

@Serializable
data class RootWord(val word: String, val pos: String, val meaningBn: String)

@Serializable
data class RootFamily(
    val id: String,
    val root: String,
    val statedCount: Int,
    val rootPlusSuffix: List<RootWord>,
    val prefixPlusRoot: List<RootWord>,
) {
    val size get() = rootPlusSuffix.size + prefixPlusRoot.size
}

@Serializable
data class MemoryHook(
    val id: String,
    val order: Int,
    val word: String,
    val ipa: String,
    val bnPronunciation: String,
    val pos: String,
    val meaningBn: String,
    val meaningEn: String,
    val soundSplit: String,
    val soundHookBn: String,
    val storyBn: String,
    val keyCueBn: String,
    val exampleEn: String,
    val exampleBn: String,
    val synonyms: List<String>,
)

@Serializable
data class PairSide(
    val word: String,
    val pos: String,
    val ipa: String,
    val bnPronunciation: String,
    val meaningBn: String,
    val exampleEn: String = "",
    val exampleBn: String = "",
)

@Serializable
data class ConfusedPair(
    val id: String,
    val order: Int,
    val isHomophone: Boolean,
    val a: PairSide,
    val b: PairSide,
    val differenceBn: String,
    val mnemonic: String,
)

@Serializable
data class SynAnt(
    val id: String,
    val word: String,
    val pos: String,
    val meaningBn: String,
    val synonyms: List<String>,
    val antonyms: List<String>,
)

@Serializable
data class OneWord(
    val id: String,
    val descriptionEn: String,
    val answer: String,
    val meaningBn: String,
    val categoryBn: String,
    val categoryEn: String,
)

@Serializable
data class Mcq(
    val id: String,
    val set: Int,
    val level: String,
    val number: Int,
    val type: String,
    val question: String,
    val options: Map<String, String>,
    val answer: String,
)

val OPTION_KEYS = listOf("ka", "kha", "ga", "gha")
val OPTION_LABELS = mapOf("ka" to "ক", "kha" to "খ", "ga" to "গ", "gha" to "ঘ")

